declare
    may_update boolean;
    may_complete boolean;
    plan_item_count integer;

    old_business_state jsonb;
    new_business_state jsonb;
begin

    may_update :=
        public.has_permission(
            new.workspace_id,
            'daily_plan.update'
        );

    may_complete :=
        public.has_permission(
            new.workspace_id,
            'daily_plan.complete'
        );


    -- --------------------------------------------------------
    -- INSERT
    -- --------------------------------------------------------

    if tg_op = 'INSERT' then

        -- prepare_daily_plan_insert() also sets these values.
        -- We repeat the rule here intentionally so lifecycle
        -- behavior remains explicit.

        new.status := 'draft';

        new.todays_one_thing_action_id := null;

        new.grade := null;
        new.score := null;
        new.completed_at := null;

        return new;

    end if;


    -- --------------------------------------------------------
    -- Immutable identity / origin fields.
    -- --------------------------------------------------------

    if new.id <> old.id then
        raise exception
            'Daily Plan id is immutable';
    end if;


    if new.workspace_id <> old.workspace_id then
        raise exception
            'Daily Plan Workspace is immutable';
    end if;


    if new.plan_date <> old.plan_date then
        raise exception
            'Daily Plan date is immutable';
    end if;


    if new.version_number <> old.version_number then
        raise exception
            'Daily Plan version is immutable';
    end if;


    if new.generated_at <> old.generated_at then
        raise exception
            'Daily Plan generated_at is immutable';
    end if;


    if new.created_at <> old.created_at then
        raise exception
            'Daily Plan created_at is immutable';
    end if;


    if new.created_by_principal_id
       is distinct from old.created_by_principal_id then

        raise exception
            'Daily Plan creator is immutable';

    end if;


    -- --------------------------------------------------------
    -- Historical plans are immutable.
    -- --------------------------------------------------------

    if old.status in (
        'completed',
        'superseded'
    ) then

        raise exception
            'Completed or superseded Daily Plans are immutable';

    end if;


    -- --------------------------------------------------------
    -- Draft remains Draft.
    --
    -- Full editing is allowed with daily_plan.update.
    -- --------------------------------------------------------

    if old.status = 'draft'
       and new.status = 'draft' then

        if not may_update then
            raise exception
                'Permission daily_plan.update is required to edit a draft Daily Plan';
        end if;


        -- Grade belongs to the completed historical day,
        -- not a draft plan.

        if new.grade is not null
           or new.score is not null
           or new.completed_at is not null then

            raise exception
                'Draft Daily Plans cannot contain a final grade, score, or completion timestamp';

        end if;


        return new;

    end if;


    -- --------------------------------------------------------
    -- Draft → Active
    -- --------------------------------------------------------

    if old.status = 'draft'
       and new.status = 'active' then

        if not may_update then
            raise exception
                'Permission daily_plan.update is required to activate a Daily Plan';
        end if;


        -- A candidate-facing active Plan should contain actual
        -- work.

        select count(*)
        into plan_item_count
        from public.daily_plan_items
        where workspace_id = new.workspace_id
          and daily_plan_id = new.id;


        if plan_item_count = 0 then
            raise exception
                'A Daily Plan must contain at least one Plan Item before activation';
        end if;


        -- ----------------------------------------------------
        -- Supersede any previously active Plan for the same
        -- Workspace and date.
        --
        -- This preserves v1 rather than rewriting it.
        -- ----------------------------------------------------

        update public.daily_plans
        set status = 'superseded'
        where workspace_id = new.workspace_id
          and plan_date = new.plan_date
          and status = 'active'
          and id <> new.id;


        new.grade := null;
        new.score := null;
        new.completed_at := null;

        return new;

    end if;


    -- --------------------------------------------------------
    -- Draft → Superseded
    --
    -- Useful when a generated draft is abandoned before it ever
    -- becomes the candidate-facing Plan.
    -- --------------------------------------------------------

    if old.status = 'draft'
       and new.status = 'superseded' then

        if not may_update then
            raise exception
                'Permission daily_plan.update is required to supersede a draft Daily Plan';
        end if;


        old_business_state :=
            to_jsonb(old)
            - array[
                'status',
                'updated_at',
                'updated_by_principal_id'
            ];


        new_business_state :=
            to_jsonb(new)
            - array[
                'status',
                'updated_at',
                'updated_by_principal_id'
            ];


        if old_business_state
           is distinct from new_business_state then

            raise exception
                'Daily Plan content cannot change while marking the draft superseded';

        end if;


        return new;

    end if;


    -- --------------------------------------------------------
    -- Active remains Active
    --
    -- Structural reprioritization should create another Plan
    -- version rather than silently rewriting history.
    -- --------------------------------------------------------

    if old.status = 'active'
       and new.status = 'active' then

        old_business_state :=
            to_jsonb(old)
            - array[
                'updated_at',
                'updated_by_principal_id'
            ];


        new_business_state :=
            to_jsonb(new)
            - array[
                'updated_at',
                'updated_by_principal_id'
            ];


        if old_business_state
           is distinct from new_business_state then

            raise exception
                'Active Daily Plan content is frozen; create a new Plan version for reprioritization';

        end if;


        return new;

    end if;


    -- --------------------------------------------------------
    -- Active → Completed
    -- --------------------------------------------------------

    if old.status = 'active'
       and new.status = 'completed' then

        if not may_complete then
            raise exception
                'Permission daily_plan.complete is required to complete a Daily Plan';
        end if;


        -- Structural plan content must not change during
        -- completion.
        --
        -- Grade / score / summary may be finalized.

        old_business_state :=
            to_jsonb(old)
            - array[
                'status',
                'grade',
                'score',
                'summary',
                'completed_at',
                'updated_at',
                'updated_by_principal_id'
            ];


        new_business_state :=
            to_jsonb(new)
            - array[
                'status',
                'grade',
                'score',
                'summary',
                'completed_at',
                'updated_at',
                'updated_by_principal_id'
            ];


        if old_business_state
           is distinct from new_business_state then

            raise exception
                'Daily Plan structure cannot change during completion';
        end if;


        if new.grade is null
           or new.score is null then

            raise exception
                'Completed Daily Plans require both a grade and numeric score';

        end if;


        if new.completed_at is null then
            new.completed_at := now();
        end if;


        return new;

    end if;


    -- --------------------------------------------------------
    -- Active → Superseded
    --
    -- This normally happens automatically when a newer version
    -- becomes active.
    -- --------------------------------------------------------

    if old.status = 'active'
       and new.status = 'superseded' then

        if not may_update then
            raise exception
                'Permission daily_plan.update is required to supersede a Daily Plan';
        end if;


        old_business_state :=
            to_jsonb(old)
            - array[
                'status',
                'updated_at',
                'updated_by_principal_id'
            ];


        new_business_state :=
            to_jsonb(new)
            - array[
                'status',
                'updated_at',
                'updated_by_principal_id'
            ];


        if old_business_state
           is distinct from new_business_state then

            raise exception
                'Daily Plan content cannot change while marking the Plan superseded';

        end if;


        return new;

    end if;


    -- --------------------------------------------------------
    -- Everything else is invalid.
    -- --------------------------------------------------------

    raise exception
        'Invalid Daily Plan lifecycle transition: % → %',
        old.status,
        new.status;

end;

declare candidate uuid; action_ids uuid[];
begin
  candidate:=private.hq_workspace_candidate(w);
  if not public.has_permission(w,'next_action.read') or not public.has_permission(w,'daily_plan.read') then
    raise exception using errcode='42501',message='Planner read authority required';
  end if;
  if p is not null then
    perform id from public.daily_plans where workspace_id=w and id=p and status='active' for share;
    if not found then raise exception 'Active scoped Plan required'; end if;
  end if;
  -- Capture only rows actually locked by this statement. A later INSERT must
  -- not enter a subsequent invoker read without its own eligibility lock.
  select coalesce(array_agg(q.id order by q.id),'{}'::uuid[]) into action_ids
    from (select id from public.next_actions where workspace_id=w and status='open' order by id for share) q;
  return jsonb_build_object('candidate_principal_id',candidate,'locked_action_ids',action_ids,'checked_at',clock_timestamp());
end;

declare ids uuid[];
begin
  if not public.is_active_workspace_principal(w,public.current_principal_id())
     or not public.has_permission(w,'workspace.read')
     or not exists(select 1 from public.workspaces where id=w and status='active') then
    raise exception using errcode='42501',message='Active workspace authority required';
  end if;
  select array_agg(p.id order by p.id) into ids
    from public.workspace_memberships m join public.principals p on p.id=m.principal_id
    join public.roles r on r.id=m.role_id
    where m.workspace_id=w and m.status='active' and p.status='active'
      and p.principal_type='human' and r.workspace_id is null and lower(r.name)='owner';
  if coalesce(cardinality(ids),0)<>1 then
    raise exception 'Workspace candidate authority is ambiguous';
  end if;
  return ids[1];
end;

declare
    lock_key bigint;
begin

    lock_key :=
        hashtextextended(
            new.workspace_id::text
            || ':daily_plan:'
            || new.plan_date::text,
            0
        );

    perform pg_advisory_xact_lock(lock_key);


    select coalesce(max(version_number), 0) + 1
    into new.version_number
    from public.daily_plans
    where workspace_id = new.workspace_id
      and plan_date = new.plan_date;


    -- New plans always begin as drafts.

    new.status := 'draft';

    new.completed_at := null;

    new.grade := null;

    new.score := null;


    return new;

end;

declare
    actor_id uuid;
begin

    actor_id := public.current_principal_id();

    if tg_op = 'INSERT' then

        if actor_id is not null then
            new.created_by_principal_id := actor_id;

            if to_jsonb(new) ? 'updated_by_principal_id' then
                new.updated_by_principal_id := actor_id;
            end if;
        end if;

    elsif tg_op = 'UPDATE' then

        if actor_id is not null
           and to_jsonb(new) ? 'updated_by_principal_id' then

            new.updated_by_principal_id := actor_id;

        end if;

    end if;

    return new;

end;
